// ===========================================================================
// Delivery-protocol rules (PZ020..PZ026).
//
// These are the BUILD gate's mechanical half.
// Each message is written as a machine-generated prompt: what is wrong, then
// the one line that fixes it — a verdict failure is a work order, not a wall.
// ===========================================================================

// App source = the code this app actually ships. Tests, scripts and tool
// configs are excluded on purpose: a fixture importing sqlite, or a Playwright
// config reading PW_BASE_URL, is the harness doing it, not the app.
export const NON_APP_DIRS = /(^|\/)(tests?|__tests__|e2e|scripts)\//;
export const TEST_FILE_NAME = /\.(test|spec)\.[cm]?[jt]sx?$/;
export const CONFIG_FILE_NAME = /(^|\/)[A-Za-z0-9_.-]*\.config\.[cm]?[jt]sx?$/;

export function isAppSource(filePath, rel) {
  return isCodeFile(filePath) && !NON_APP_DIRS.test(rel) && !TEST_FILE_NAME.test(rel) && !CONFIG_FILE_NAME.test(rel);
}

export function appSourceFiles(projectDir, files) {
  return files
    .map((filePath) => ({ filePath, rel: normalizeRel(projectDir, filePath) }))
    .filter((entry) => isAppSource(entry.filePath, entry.rel));
}


// PZ020 — business records belong to the platform. A local table is a second
// source of truth that nothing else in the system can see.
export const LOCAL_DB_IMPORTS = [
  '@prisma/client', 'better-sqlite3', 'drizzle-orm', 'knex', 'mongoose', 'mysql2', 'pg', 'prisma', 'sqlite3',
];
export const LOCAL_DB_IMPORT = new RegExp(
  `(?:from|import|require)\\s*\\(?\\s*['"\`](${LOCAL_DB_IMPORTS.map(escapeForRegExp).join('|')})(?:/[^'"\`]*)?['"\`]`,
);
export const CREATE_TABLE = /\bCREATE\s+TABLE\b/i;

export function scanLocalDatabaseUsage(projectDir, files, findings) {
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    const imported = LOCAL_DB_IMPORT.exec(content);
    const created = imported ? null : CREATE_TABLE.exec(content);
    if (!imported && !created) continue;
    const what = imported ? `imports ${imported[1]}` : 'creates a table with raw SQL (CREATE TABLE)';
    addFinding(
      findings,
      'error',
      'PZ020',
      `Piezas-backed business data must not live in a local database — ${rel} ${what}. `
        + 'Move those records to the Piezas services through @piezas/sdk and delete the local schema.',
      rel,
      lineNumber(content, (imported ?? created).index),
    );
  }
}

// PZ021 — a NEXT_PUBLIC_/VITE_/PUBLIC_ prefix means "compiled into the browser
// bundle". A secret with that prefix is already published.
// PUBLISHABLE keys are browser-safe by design (users service public path; the
// contract tells apps to ship them with a public prefix), so they are exempt.
// So is Supabase's "anon" key: it is public by design (row-level security
// protects the data). Its service_role key is a full-access secret and is not.
export const PUBLIC_SECRET_NAME = /\b(?:NEXT_PUBLIC|VITE|PUBLIC)_(?![A-Z0-9_]*PUBLISHABLE)(?![A-Z0-9_]*SUPABASE_ANON_KEY\b)[A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD)[A-Z0-9_]*\b/g;

export function scanPublicSecretNames(projectDir, files, findings) {
  for (const filePath of files) {
    const rel = normalizeRel(projectDir, filePath);
    const isEnvFile = basename(rel).startsWith('.env');
    if (!isEnvFile && !isAppSource(filePath, rel)) continue;
    const content = readFileSync(filePath, 'utf-8');
    const seen = new Set();
    PUBLIC_SECRET_NAME.lastIndex = 0;
    let match = PUBLIC_SECRET_NAME.exec(content);
    while (match) {
      if (!seen.has(match[0])) {
        seen.add(match[0]);
        addFinding(
          findings,
          'error',
          'PZ021',
          `${match[0]} ships to the browser: the NEXT_PUBLIC_/VITE_/PUBLIC_ prefix publishes it to every visitor. `
            + `Drop the public prefix, read the value server-side only, and rotate the credential if it has been deployed.`,
          rel,
          lineNumber(content, match.index),
        );
      }
      match = PUBLIC_SECRET_NAME.exec(content);
    }
  }
}

// PZ022 — a Next app that runs server code must build a standalone server, or
// there is nothing for `piezas deploy` to ship. PZ011 asks the same question of
// the DECLARED deployment mode; this one asks it of the app as written.
export function hasNextServerSurface(projectDir, files) {
  return files.some((filePath) => {
    const rel = normalizeRel(projectDir, filePath);
    return (
      /^(src\/)?app\/api\//.test(rel) ||
      /^(src\/)?pages\/api\//.test(rel) ||
      /^(src\/)?middleware\.[cm]?[tj]s$/.test(rel)
    );
  });
}

export function scanStandaloneOutputRequired(projectDir, files, findings) {
  const pkg = packageJson(projectDir);
  if (!pkg?.dependencies?.next && !pkg?.devDependencies?.next) return;
  if (!hasNextServerSurface(projectDir, files)) return;
  const config = findNextConfig(projectDir);
  if (config && /output\s*:\s*['"`]standalone['"`]/.test(config.text)) return;
  addFinding(
    findings,
    'error',
    'PZ022',
    `This Next app runs server code (API routes or middleware), but ${config ? config.name : 'no next.config.js|mjs|ts'} `
      + "sets output: 'standalone' — so the build produces no .next/standalone/server.js and the deploy has nothing to ship. "
      + `Add output: 'standalone', to ${config ? config.name : 'a next.config.mjs'}, then run npm run build.`,
    config?.name ?? 'next.config.mjs',
  );
}

// PZ023 — the manifest's requiredEnv is what `piezas deploy` checks against the
// HOSTED environment before it uploads. A variable the app reads but never
// declares is a variable that boots missing, in production, silently.
export const ENV_READ = /process\.env\s*(?:\.\s*([A-Za-z_][A-Za-z0-9_]*)|\[\s*['"`]([A-Za-z_][A-Za-z0-9_]*)['"`]\s*\])/g;
// Provided by the runtime or provisioned by the platform — never declared.
export const AUTO_PROVISIONED_ENV = new Set(['NODE_ENV', 'PORT', 'HOSTNAME', 'PIEZAS_API_KEY', 'PIEZAS_API_URL']);

export function scanRequiredEnvAccuracy(projectDir, files, manifest, findings) {
  const declared = new Set(
    Array.isArray(manifest?.deploy?.requiredEnv)
      ? manifest.deploy.requiredEnv.filter((name) => typeof name === 'string')
      : [],
  );
  const missing = new Map();
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    ENV_READ.lastIndex = 0;
    let match = ENV_READ.exec(content);
    while (match) {
      const name = match[1] ?? match[2];
      if (name && !AUTO_PROVISIONED_ENV.has(name) && !declared.has(name) && !missing.has(name)) {
        missing.set(name, rel);
      }
      match = ENV_READ.exec(content);
    }
  }
  if (missing.size === 0) return;
  const names = [...missing.keys()].sort();
  addFinding(
    findings,
    'error',
    'PZ023',
    `The app reads env this project never declares: ${names.join(', ')}. `
      + 'Add them to deploy.requiredEnv in piezas.manifest.json (deploy verifies that list against the hosted '
      + 'environment and refuses to upload an app that would boot without it).',
    'piezas.manifest.json',
  );
}

// PZ024 — one commit is all it takes. Unlike PZ001 (which only speaks up when
// .env already holds a Piezas key) this asks the question unconditionally.
export function scanEnvIgnored(projectDir, findings) {
  const gitignorePath = resolve(projectDir, '.gitignore');
  const exists = existsSync(gitignorePath);
  const covered = exists
    && readFileSync(gitignorePath, 'utf-8')
      .split(/\r?\n/)
      .some((line) => GITIGNORE_ENV_PATTERNS.has(line.trim()));
  if (covered) return;
  addFinding(
    findings,
    'error',
    'PZ024',
    `.env is not git-ignored (${exists ? '.gitignore has no .env pattern' : 'there is no .gitignore'}) — one commit `
      + 'publishes every key in it. Add a line reading .env to .gitignore (or run `npx piezas init`, which writes it).',
    '.gitignore',
  );
}

// PZ025 — the BUILD gate, reported where the agent is already looking. Doctor
// repeats spec check + scenario coverage verbatim: same rule ids, same named
// gaps, so the repair prompt is identical wherever it is read.
export function scanScenarioCoverage(projectDir, findings) {
  if (!existsSync(join(projectDir, SPEC_FILE))) return;
  const gaps = [...checkSpec(projectDir).gaps, ...checkCoverage(projectDir).gaps];
  const seen = new Set();
  for (const entry of gaps) {
    const key = `${entry.rule}: ${entry.message}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const fix = entry.rule === 'COVERAGE'
      ? 'Write that scenario test, then re-run `npx piezas spec coverage`.'
      : 'Close the gap with the customer in SPEC.md, then re-run `npx piezas spec check`.';
    addFinding(findings, 'error', 'PZ025', `${key} — ${fix}`, SPEC_FILE);
  }
}

// PZ026 — a NOTICE, never a gate. Scenario tests select by data-testid; an app
// without them forces text/CSS selectors that break on the next redesign.
export const INTERACTIVE_TAG = /<(button|input|select|a)(?=[\s/>])/g;

// jsxTagText returns an element's opening tag, tracking braces and quotes so a
// `>` inside {() => x} or a string does not end the tag early. Bounded, so an
// unbalanced brace cannot run the scan to the end of the file.
export function jsxTagText(content, start) {
  const limit = Math.min(content.length, start + 800);
  let depth = 0;
  let quote = null;
  for (let i = start; i < limit; i += 1) {
    const char = content[i];
    if (quote) {
      if (char === quote && content[i - 1] !== '\\') quote = null;
      continue;
    }
    if (char === '"' || char === "'" || char === '`') quote = char;
    else if (char === '{') depth += 1;
    else if (char === '}') depth -= 1;
    else if (char === '>' && depth === 0) return content.slice(start, i + 1);
  }
  return content.slice(start, limit);
}

export function scanTestIdCoverage(projectDir, files, findings) {
  let untagged = 0;
  const fileSet = new Set();
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    INTERACTIVE_TAG.lastIndex = 0;
    let match = INTERACTIVE_TAG.exec(content);
    while (match) {
      if (!jsxTagText(content, match.index).includes('data-testid')) {
        untagged += 1;
        fileSet.add(rel);
      }
      match = INTERACTIVE_TAG.exec(content);
    }
  }
  if (untagged === 0) return;
  addFinding(
    findings,
    'notice',
    'PZ026',
    `${untagged} interactive element(s) across ${fileSet.size} file(s) have no data-testid, so scenario tests must `
      + 'select them by text or CSS and will break on the next redesign. Add data-testid to the elements your '
      + 'S-nnn scenarios drive (tests/scenarios/README.md has the convention).',
  );
}

// isNewerContract: contract versions are hand-bumped revisions ("1", "2", ...),
// so a numeric comparison is the honest one. When either side is not a number
// (a future scheme), "different from what the service serves" is the most we
// can claim — and it is still worth saying.
export function isNewerContract(live, local) {
  const liveNumber = Number(live);
  const localNumber = Number(local);
  if (Number.isFinite(liveNumber) && Number.isFinite(localNumber)) {
    return liveNumber > localNumber;
  }
  return live !== local;
}

// scanContractFreshness (PZ012): the contract is SERVED, so the copy sitting in
// this project is a cache — and a cache of RULES that silently goes stale is
// exactly what this check exists to prevent. It asks the cheap
// /contract/version probe (no 40KB transfer) and says nothing at all when that
// probe fails: a doctor that fails offline is noise, not a finding.
export async function scanContractFreshness(manifest, findings, options) {
  const local = typeof manifest.contractVersion === 'string' && manifest.contractVersion
    ? manifest.contractVersion
    : null;
  if (!local) {
    // 'notice', not 'warn': every project created before contract fetching
    // existed has no recorded version, and turning `doctor --strict` red for
    // all of them on upgrade would break CI for a state the user has not done
    // anything wrong to reach. It is reported, it just does not fail the gate.
    // Being BEHIND a served version (below) is a real warn — that one is
    // actionable and self-inflicted-by-time.
    addFinding(
      findings,
      'notice',
      'PZ012',
      'This project has no recorded contract version, so its Piezas instructions came from a CLI bundle instead of the served contract. Run `npx piezas init` to adopt the contract the platform serves today.',
      'piezas.manifest.json',
    );
    return;
  }

  const env = options.env ?? process.env;
  const contractUrl = resolveContractUrl(options, env);
  let probe;
  try {
    probe = await fetchJson(options.fetchFn ?? fetch, `${contractUrl}/version`, {
      timeoutMs: CONTRACT_TIMEOUT_MS,
    });
  } catch {
    return; // offline / timeout — stay silent
  }
  if (!probe || probe.status !== 200) return;
  const live = probe.data?.version === undefined || probe.data?.version === null
    ? ''
    : String(probe.data.version).trim();
  if (!live || !isNewerContract(live, local)) return;

  addFinding(
    findings,
    'warn',
    'PZ012',
    `This project is on contract v${local}; ${contractUrl} now serves v${live}. Run \`npx piezas init\` to refresh the agent instruction files.`,
    'piezas.manifest.json',
  );
}

export async function runDoctor(projectDir, options = {}) {
  const resolvedDir = resolve(projectDir);
  const findings = [];
  const manifestInfo = loadManifest(resolvedDir, findings);
  const files = existsSync(resolvedDir) ? listFiles(resolvedDir) : [];

  scanSecretExposure(resolvedDir, files, findings);
  scanDeploymentMode(resolvedDir, files, manifestInfo.manifest, findings);
  scanLocalDatabase(resolvedDir, files, findings);
  scanOAuthTokenStorage(resolvedDir, files, findings);
  scanAdminTokenInUrl(resolvedDir, files, findings);
  scanHiddenTimeTrust(resolvedDir, files, findings);
  scanUnusedDynamicRoutes(resolvedDir, files, findings);
  scanIntegrationActions(resolvedDir, files, findings);
  scanAuthEmailReturnUrl(resolvedDir, files, findings);
  scanCoverageConfig(resolvedDir, files, findings);
  scanPackageScripts(resolvedDir, findings);
  scanNextStandaloneOutput(resolvedDir, manifestInfo.manifest, findings);
  // The delivery-protocol rules. PZ023 judges the manifest's declarations, so
  // it only speaks where there IS a manifest — a missing one already got PZ000
  // ("run init"), and listing every env var of an un-init'd folder is noise.
  scanLocalDatabaseUsage(resolvedDir, files, findings);
  scanPublicSecretNames(resolvedDir, files, findings);
  scanStandaloneOutputRequired(resolvedDir, files, findings);
  if (manifestInfo.exists) {
    scanRequiredEnvAccuracy(resolvedDir, files, manifestInfo.manifest, findings);
  }
  scanEnvIgnored(resolvedDir, findings);
  scanScenarioCoverage(resolvedDir, findings);
  scanTestIdCoverage(resolvedDir, files, findings);
  // Only for a real project: a missing manifest already got PZ000 ("run init"),
  // which is the same advice PZ012 would repeat.
  if (manifestInfo.exists) {
    await scanContractFreshness(manifestInfo.manifest, findings, options);
  }

  const errors = findings.filter((finding) => finding.severity === 'error').length;
  const warnings = findings.filter((finding) => finding.severity === 'warn').length;
  // 'notice' findings are informational: printed, never gating. --strict
  // promotes warnings to failures; it must not promote notices, or upgrading
  // the CLI would fail every pre-existing project's CI.
  const notices = findings.filter((finding) => finding.severity === 'notice').length;

  return {
    projectDir: resolvedDir,
    manifest: manifestInfo.manifest,
    manifestFound: manifestInfo.exists,
    findings,
    errors,
    warnings,
    notices,
    passed: errors === 0 && (!options.strict || warnings === 0),
  };
}

export function formatDoctorResult(result) {
  const lines = [
    '',
    '  🧱 Piezas Doctor',
    '',
    `  Project: ${result.projectDir}`,
    `  Manifest: ${result.manifestFound ? 'found' : 'missing'}`,
    `  Deployment mode: ${result.manifest.deploymentMode || 'unknown'}`,
    '',
  ];

  if (result.findings.length === 0) {
    lines.push('  No issues found.');
  } else {
    for (const finding of result.findings) {
      const marker =
        finding.severity === 'error' ? 'ERROR' : finding.severity === 'notice' ? 'NOTE ' : 'WARN ';
      const location = finding.file
        ? ` (${finding.file}${finding.line ? `:${finding.line}` : ''})`
        : '';
      lines.push(`  ${marker} ${finding.code}${location}`);
      lines.push(`        ${finding.message}`);
    }
  }

  lines.push('');
  lines.push(
    `  Summary: ${result.errors} error(s), ${result.warnings} warning(s)` +
      (result.notices ? `, ${result.notices} note(s)` : ''),
  );
  lines.push('');
  return lines.join('\n');
}

// ===========================================================================
// The delivery protocol: state, spec verdicts, phase gates, hook guard.
//
// Everything below is AGENT-FIRST: terse deterministic lines, stable rule IDs,
// exit codes that carry the verdict. It is the engine the Claude Code plugin
// drives — the plugin is choreography, this is judgment.
// ===========================================================================

export const PHASES = ['discover', 'mock', 'build', 'ship'];
export const NEXT_PHASE = { discover: 'mock', mock: 'build', build: 'ship' };
export const STATE_VERSION = 1;
export const STATE_FILE = 'state.json';
export const STATE_REL = `${STATE_DIR}/${STATE_FILE}`;
export const SPEC_FILE = 'SPEC.md';
export const SCENARIO_TEST_DIR = 'tests/scenarios';
export const SCENARIO_TEST_EXTENSIONS = ['.spec.ts', '.spec.js'];
// The only gate a human signs today: the customer approving INTENT on the mock.
export const APPROVAL_GATES = new Set(['mock']);
export const GATE_BY_PHASE = {
  discover: 'spec-check',
  mock: 'user-approval',
  build: 'scenario-coverage',
  ship: 'deploy-attestation',
};

export const RUN_INIT_HINT = 'run `npx piezas phase init`';

export function toPosix(value) {
  return value.split('\\').join('/');
}

// findProjectRoot walks up from startDir for the directory holding
// .piezas/state.json. The STATE FILE (not the .piezas dir) is the anchor:
// `piezas init` creates .piezas/ for the spec-builder doc alone, and a project
// without state is not a protocol project — the guard must stay silent there.
export function findProjectRoot(startDir = process.cwd()) {
  let dir = resolve(startDir);
  for (;;) {
    if (existsSync(join(dir, STATE_DIR, STATE_FILE))) return dir;
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

// childProjects — Piezas projects in the folders just below dir (two levels),
// for a session opened in the folder that CONTAINS the app.
export function childProjects(dir, depth = 2) {
  const found = [];
  const walk = (d, left) => {
    let entries;
    try { entries = readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (!e.isDirectory() || e.isSymbolicLink() || e.name.startsWith('.') || e.name === 'node_modules') continue;
      const child = join(d, e.name);
      if (existsSync(join(child, STATE_DIR, STATE_FILE))) found.push(child);
      else if (left > 1) walk(child, left - 1);
    }
  };
  walk(resolve(dir), depth);
  return found.sort();
}

// sessionRoot — the project a session works on: the one it is inside, or the
// only one just below it.
export function sessionRoot(cwd) {
  const inside = findProjectRoot(cwd);
  if (inside) return { root: inside, below: false };
  const below = childProjects(cwd);
  return below.length === 1 ? { root: below[0], below: true } : { root: null, below: false, several: below };
}

export function stateError(message) {
  const error = new Error(message);
  error.protocol = true;
  return error;
}

export function requireProjectRoot(startDir) {
  const root = findProjectRoot(startDir);
  if (!root) {
    throw stateError(`no Piezas project state (${STATE_REL}) at or above ${resolve(startDir)} — ${RUN_INIT_HINT}`);
  }
  return root;
}

export function validateState(parsed) {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return 'not an object';
  if (parsed.version !== STATE_VERSION) return `unsupported version ${JSON.stringify(parsed.version)} (expected ${STATE_VERSION})`;
  if (!PHASES.includes(parsed.phase)) return `unknown phase ${JSON.stringify(parsed.phase)}`;
  if (!Array.isArray(parsed.approvals)) return 'approvals is not an array';
  for (const approval of parsed.approvals) {
    if (!approval || typeof approval.gate !== 'string' || typeof approval.by !== 'string' || typeof approval.at !== 'string') {
      return 'an approval entry is missing gate/by/at';
    }
  }
  return null;
}

// loadState reads the state for the project containing startDir. Missing or
// corrupt state is a HARD error with a repair instruction — never a silent
// default, because a defaulted phase is an unlocked phase.
export function loadState(startDir = process.cwd()) {
  const root = requireProjectRoot(startDir);
  const filePath = join(root, STATE_DIR, STATE_FILE);
  let parsed;
  try {
    parsed = JSON.parse(readFileSync(filePath, 'utf-8'));
  } catch (error) {
    throw stateError(`${STATE_REL} is not readable JSON (${error?.message || error}) — delete it and ${RUN_INIT_HINT}`);
  }
  const problem = validateState(parsed);
  if (problem) {
    throw stateError(`${STATE_REL} is invalid: ${problem} — delete it and ${RUN_INIT_HINT}`);
  }
  return {
    version: STATE_VERSION,
    phase: parsed.phase,
    approvals: parsed.approvals,
    createdAt: typeof parsed.createdAt === 'string' ? parsed.createdAt : null,
    updatedAt: typeof parsed.updatedAt === 'string' ? parsed.updatedAt : null,
  };
}

// saveState writes the v1 schema and nothing else: extra keys on the passed
// object are dropped, so callers can spread a loaded state freely. updatedAt is
// always stamped here — no caller sets it.
export function saveState(startDir, state) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const now = new Date().toISOString();
  const next = {
    version: STATE_VERSION,
    phase: state.phase,
    approvals: Array.isArray(state.approvals) ? state.approvals : [],
    createdAt: typeof state.createdAt === 'string' ? state.createdAt : now,
    updatedAt: now,
  };
  const problem = validateState(next);
  if (problem) throw stateError(`refusing to write invalid state: ${problem}`);
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, STATE_FILE), `${JSON.stringify(next, null, 2)}\n`);
  return next;
}

// --- SPEC.md: the parser and the six rules -------------------------------

// Unresolved markers are matched CASE-SENSITIVELY: a to-do app's spec says
// "todo item" all over, and only the shouting form is a placeholder.
export const UNRESOLVED_MARKER = /\bTBD\b|\bTODO\b|\bUNRESOLVED\b|\[\?\]/g;
export const REQUIREMENT_LINE = /^\s*[-*]\s*\**\s*(R-\d+)\s*\**\s*:/;
export const SCENARIO_HEADING = /^###\s*\**\s*(S-\d+)\s*\**\s*:\s*(.*)$/;
export const COVERS_LINE = /^\s*(?:[-*]\s*)?\**\s*covers\s*\**\s*:\s*(.+)$/i;
export const GWT_LINE = /^\s*(?:[-*]\s*)?\**\s*(Given|When|Then)\b/;

// blankComments removes HTML comments while PRESERVING line numbers, so the
// template's format guidance can name the banned markers without tripping
// SPEC05 and every reported line number still matches the file.
export function blankComments(text) {
  return text.replace(/<!--[\s\S]*?-->/g, (match) => match.replace(/[^\n]/g, ''));
}

// splitSections maps "## Heading" -> the lines beneath it (with 1-based line
// numbers). "###" scenario headings stay inside their parent section.
export function splitSections(lines) {
  const sections = new Map();
  let current = null;
  lines.forEach((text, index) => {
    const heading = /^##\s+(.+?)\s*$/.exec(text);
    if (heading) {
      current = { title: heading[1].trim(), line: index + 1, lines: [] };
      sections.set(current.title.toLowerCase(), current);
      return;
    }
    if (current) current.lines.push({ text, number: index + 1 });
  });
  return sections;
}

export function parseSpec(text) {
  const lines = blankComments(text).split(/\r?\n/);
  const sections = splitSections(lines);

  const requirementsSection = sections.get('requirements');
  const requirements = (requirementsSection?.lines ?? [])
    .map((line) => {
      const match = REQUIREMENT_LINE.exec(line.text);
      return match ? { id: match[1], line: line.number } : null;
    })
    .filter(Boolean);

  const scenariosSection = sections.get('acceptance scenarios');
  const scenarios = [];
  for (const line of scenariosSection?.lines ?? []) {
    const heading = SCENARIO_HEADING.exec(line.text);
    if (heading) {
      scenarios.push({
        id: heading[1],
        title: heading[2].trim(),
        line: line.number,
        covers: [],
        given: false,
        when: false,
        then: false,
      });
      continue;
    }
    const current = scenarios[scenarios.length - 1];
    if (!current) continue;
    const covers = COVERS_LINE.exec(line.text);
    if (covers) {
      for (const token of covers[1].split(',')) {
        const id = /R-\d+/.exec(token);
        if (id) current.covers.push(id[0]);
      }
      continue;
    }
    const gwt = GWT_LINE.exec(line.text);
    if (gwt) current[gwt[1].toLowerCase()] = true;
  }

  const markers = [];
  lines.forEach((text, index) => {
    UNRESOLVED_MARKER.lastIndex = 0;
    let match;
    while ((match = UNRESOLVED_MARKER.exec(text)) !== null) {
      markers.push({ marker: match[0], line: index + 1 });
    }
  });

  return { lines, sections, requirements, scenarios, markers };
}

export function openConflictsLeft(sections) {
  const section = sections.get('open conflicts');
  if (!section) return [];
  return section.lines
    .map((line) => line.text.trim())
    .filter((text) => text.length > 0)
    .filter((text) => text.replace(/^[-*]\s*/, '').replace(/[.\s]/g, '').toLowerCase() !== 'none');
}

export function gap(rule, message) {
  return { rule, message };
}

// checkSpec is the DISCOVER gate. Every failure is a named gap — a
// machine-generated work order the agent can close, one at a time.
export function checkSpec(projectDir) {
  const specPath = join(resolve(projectDir), SPEC_FILE);
  const empty = { command: 'spec check', specPath, requirements: [], scenarios: [] };

  if (!existsSync(specPath)) {
    return { ...empty, ok: false, gaps: [gap('SPEC01', `${SPEC_FILE} is missing — ${RUN_INIT_HINT} to create it from the template`)] };
  }
  const raw = readFileSync(specPath, 'utf-8');
  if (!raw.trim()) {
    return { ...empty, ok: false, gaps: [gap('SPEC01', `${SPEC_FILE} is empty`)] };
  }

  const parsed = parseSpec(raw);
  const gaps = [];

  // SPEC02 — requirements exist, in the checkable "- R-001: ..." form.
  if (!parsed.sections.has('requirements')) {
    gaps.push(gap('SPEC02', 'no "## Requirements" section'));
  } else if (parsed.requirements.length === 0) {
    gaps.push(gap('SPEC02', 'no requirements under "## Requirements" (expected lines like "- R-001: <claim>")'));
  }

  // SPEC03 — scenarios exist and each is a complete Given/When/Then.
  if (!parsed.sections.has('acceptance scenarios')) {
    gaps.push(gap('SPEC03', 'no "## Acceptance Scenarios" section'));
  } else if (parsed.scenarios.length === 0) {
    gaps.push(gap('SPEC03', 'no scenarios under "## Acceptance Scenarios" (expected blocks like "### S-001: <title>")'));
  } else {
    for (const scenario of parsed.scenarios) {
      const missing = ['Given', 'When', 'Then'].filter((step) => !scenario[step.toLowerCase()]);
      if (missing.length > 0) {
        gaps.push(gap('SPEC03', `${scenario.id} is missing ${missing.join('/')} line${missing.length > 1 ? 's' : ''}`));
      }
    }
  }

  // SPEC04 — the coverage claim: every requirement is exercised by a scenario.
  const covered = new Set(parsed.scenarios.flatMap((scenario) => scenario.covers));
  for (const requirement of parsed.requirements) {
    if (!covered.has(requirement.id)) {
      gaps.push(gap('SPEC04', `${requirement.id} has no covering scenario`));
    }
  }

  // SPEC05 — no placeholders. An unresolved marker is an unasked question.
  for (const marker of parsed.markers) {
    gaps.push(gap('SPEC05', `unresolved marker "${marker.marker}" at line ${marker.line}`));
  }

  // SPEC06 — conflicts are decisions the customer still owes us.
  const conflicts = openConflictsLeft(parsed.sections);
  for (const conflict of conflicts) {
    gaps.push(gap('SPEC06', `"## Open Conflicts" still lists: ${conflict}`));
  }

  return {
    command: 'spec check',
    specPath,
    ok: gaps.length === 0,
    requirements: parsed.requirements.map((entry) => entry.id),
    scenarios: parsed.scenarios.map((entry) => entry.id),
    gaps,
  };
}

// checkCoverage is the BUILD gate's mechanical half: one test file per
// scenario. It deliberately does NOT read the spec's other rules — a project
// mid-build should not be told about spec style while it is closing coverage.
export function checkCoverage(projectDir) {
  const root = resolve(projectDir);
  const specPath = join(root, SPEC_FILE);
  if (!existsSync(specPath) || !readFileSync(specPath, 'utf-8').trim()) {
    const spec = checkSpec(root);
    return { command: 'spec coverage', ok: false, scenarios: [], missing: [], gaps: spec.gaps };
  }
  const parsed = parseSpec(readFileSync(specPath, 'utf-8'));
  const scenarios = parsed.scenarios.map((entry) => entry.id);
  const missing = scenarios.filter(
    (id) => !SCENARIO_TEST_EXTENSIONS.some((ext) => existsSync(join(root, 'tests', 'scenarios', `${id}${ext}`))),
  );
  const gaps = missing.map((id) =>
    gap('COVERAGE', `${id} has no scenario test (expected ${SCENARIO_TEST_DIR}/${id}.spec.ts or ${SCENARIO_TEST_DIR}/${id}.spec.js)`),
  );
  if (scenarios.length === 0) {
    gaps.push(gap('COVERAGE', `${SPEC_FILE} declares no scenarios — nothing to prove`));
  }
  return { command: 'spec coverage', ok: gaps.length === 0, scenarios, missing, gaps };
}

export function gapLines(gaps) {
  return gaps.map((entry) => `${entry.rule}: ${entry.message}`);
}

export function formatSpecCheck(result) {
  if (!result.ok) return gapLines(result.gaps);
  return [`spec check: ok (${result.requirements.length} requirements, ${result.scenarios.length} scenarios)`];
}

export function formatSpecCoverage(result) {
  if (!result.ok) return gapLines(result.gaps);
  return [`spec coverage: ok (${result.scenarios.length} scenarios, ${result.scenarios.length} tests)`];
}

// --- piezas test: run the suite, attest the result -------------------------
//
// The BUILD gate proves a test FILE exists per scenario; only a RUN proves the
// app works. `piezas test` is that run, and its output is evidence rather than
// a claim: .piezas/test-attestation.json travels with the next deploy, so the
// platform can judge what was actually proven (total local defection ends in
// a blocked project, never a shipped lie).

export const ATTESTATION_FILE = 'test-attestation.json';
export const ATTESTATION_REL = `${STATE_DIR}/${ATTESTATION_FILE}`;
export const ATTESTATION_VERSION = 1;
// A day: long enough that a normal build/deploy loop never trips it, short
// enough that "I tested it last week" is called what it is.
export const ATTESTATION_MAX_AGE_MS = 24 * 60 * 60 * 1000;
export const DEFAULT_TEST_COMMAND = 'npx playwright test --reporter=json';

// parseTestReport reads Playwright's JSON reporter. The stats block is the
// cheap path; walking the suites is the fallback for reporters (and versions)
// that omit it. Anything we cannot count returns null — an uncounted run must
// never become a green attestation.
export function parseTestReport(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return null;
  }
  if (!data || typeof data !== 'object') return null;

  const stats = data.stats;
  if (stats && (Number.isFinite(stats.expected) || Number.isFinite(stats.unexpected))) {
    return {
      passed: (Number(stats.expected) || 0) + (Number(stats.flaky) || 0),
      failed: Number(stats.unexpected) || 0,
    };
  }

  let passed = 0;
  let failed = 0;
  const walk = (suite) => {
    for (const spec of suite?.specs ?? []) {
      if (spec.ok) passed += 1;
      else failed += 1;
    }
    for (const child of suite?.suites ?? []) walk(child);
  };
  for (const suite of data.suites ?? []) walk(suite);
  if (passed + failed === 0) return null;
  return { passed, failed };
}

export async function runTests(startDir = process.cwd(), options = {}) {
  const env = options.env ?? process.env;
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const override = typeof env.PIEZAS_TEST_CMD === 'string' ? env.PIEZAS_TEST_CMD.trim() : '';
  const command = override || DEFAULT_TEST_COMMAND;

  // The JSON reporter prints to stdout unless told otherwise; a temp file keeps
  // the report clean of whatever else the runner writes.
  const reportDir = mkdtempSync(join(tmpdir(), 'piezas-test-'));
  const reportPath = join(reportDir, 'report.json');
  let stdout = '';
  let stderr = '';
  try {
    stdout = execSync(command, {
      cwd: root,
      env: { ...env, PLAYWRIGHT_JSON_OUTPUT_NAME: reportPath },
      encoding: 'utf-8',
      stdio: ['ignore', 'pipe', 'pipe'],
      maxBuffer: 64 * 1024 * 1024,
    }) ?? '';
  } catch (error) {
    // A red suite exits non-zero — that is a RESULT, not an error. Keep the
    // output and let the report decide which of the two happened.
    stdout = typeof error?.stdout === 'string' ? error.stdout : error?.stdout?.toString?.() ?? '';
    stderr = typeof error?.stderr === 'string' ? error.stderr : error?.stderr?.toString?.() ?? '';
  }

  let report = null;
  try {
    if (existsSync(reportPath)) report = parseTestReport(readFileSync(reportPath, 'utf-8'));
  } catch { /* unreadable -> fall through to stdout */ }
  if (!report) report = parseTestReport(stdout);
  try { rmSync(reportDir, { recursive: true, force: true }); } catch { /* best-effort */ }

  const coverage = checkCoverage(root);
  const scenarios = coverage.scenarios.length;
  const covered = scenarios - coverage.missing.length;

  if (!report) {
    // No countable result: say so and attest NOTHING. A run nobody can read is
    // not a green run, and writing an attestation here would launder it.
    const detail = (stderr || stdout).split('\n').map((line) => line.trim()).filter(Boolean)[0];
    const json = { command: 'test', ok: false, ran: command, attestation: null };
    return {
      exitCode: 1,
      command: 'test',
      attestation: null,
      json,
      output: [
        `test: no results — \`${command}\` produced no JSON report`,
        ...(detail ? [`runner: ${detail.slice(0, 200)}`] : []),
        'fix: install the harness (npm install && npx playwright install), then re-run `npx piezas test`',
      ],
    };
  }

  const attestation = {
    version: ATTESTATION_VERSION,
    scenarios,
    covered,
    passed: report.passed,
    failed: report.failed,
    ranAt: new Date().toISOString(),
  };
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, ATTESTATION_FILE), `${JSON.stringify(attestation, null, 2)}\n`);

  const output = [
    `test: ${attestation.passed} passed, ${attestation.failed} failed`,
    `scenarios: ${scenarios} in ${SPEC_FILE}, ${covered} with tests`,
    `attested: ${ATTESTATION_REL} (${attestation.ranAt})`,
  ];
  if (covered < scenarios) {
    output.push(...gapLines(coverage.gaps));
  }
  return {
    exitCode: attestation.failed > 0 ? 1 : 0,
    command: 'test',
    attestation,
    json: { command: 'test', ok: attestation.failed === 0, ran: command, attestation },
    output,
  };
}

// readTestAttestation returns the attestation for a project, or null when it is
// absent OR unreadable — an unparseable file attests nothing, and saying so is
// the honest reading.
export function readTestAttestation(projectDir) {
  try {
    const parsed = readJsonFile(join(resolve(projectDir), STATE_DIR, ATTESTATION_FILE));
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
    return parsed;
  } catch {
    return null;
  }
}

// attestationWarning is v1's whole enforcement at the client: ONE line, never a
// block. Blocking here would only teach people to deploy around the CLI; the
// platform is where "untested cannot ship" gets teeth.
export function attestationWarning(attestation, now = Date.now()) {
  if (!attestation) {
    return 'deploy is untested: run `npx piezas test` first — this build ships with nothing attesting it.';
  }
  const failed = Number(attestation.failed) || 0;
  if (failed > 0) {
    return `deploy is RED: ${failed} test(s) failed in the last \`npx piezas test\` run (${attestation.ranAt}) — `
      + 'fix them and re-run before shipping.';
  }
  const ranAt = Date.parse(attestation.ranAt);
  if (!Number.isFinite(ranAt) || now - ranAt > ATTESTATION_MAX_AGE_MS) {
    return `deploy attestation is stale: the last \`npx piezas test\` run was ${attestation.ranAt} (over 24h ago) — `
      + 're-run `npx piezas test` so this deploy carries current evidence.';
  }
  return null;
}

// --- SPEC.md template ------------------------------------------------------

// The template is read by AGENTS as much as by humans: the comments carry the
// exact formats `spec check` enforces, so a fresh session can fill it without
// guessing. Comments are stripped before checking, which is why the banned
// markers can be named literally here.
export function specTemplate() {
  return `# Product Spec

<!--
Piezas SPEC.md — the contract this app is built, tested and shipped against.
\`npx piezas spec check\` enforces these formats:

  Requirement   - R-001: <one testable claim, in the customer's words>
  Scenario      ### S-002: <short title>
                covers: R-001, R-003
                Given <starting state>
                When <the action>
                Then <the observable result>

Rules the checker applies:
  SPEC02  at least one "- R-nnn:" line under "## Requirements"
  SPEC03  every "### S-nnn:" block has Given, When and Then lines
  SPEC04  every R-nnn is named by the "covers:" line of some scenario
  SPEC05  no unresolved markers anywhere: TBD, TODO, UNRESOLVED, [?]
  SPEC06  "## Open Conflicts" reads "none"

Write provenance next to each claim (which artifact or which person it came
from). Later, each S-nnn needs a test at tests/scenarios/S-nnn.spec.ts|js
before the project may advance to ship.
-->

## Overview

<!-- Two or three sentences: who uses this, and what job it does for them. -->

## Requirements

<!-- One line per claim, in business language, each independently testable:
     - R-001: A guest can reserve a table for a given date and time.
     - R-002: Staff can cancel a reservation and free the slot. -->

## Acceptance Scenarios

### S-001: Example — replace this with a real scenario

covers: R-001
Given a staff member signed in to the dashboard
When they open today's reservations
Then the reservations appear in time order

## Open Conflicts

none
`;
}

// --- spec-builder: the interview guide the agent reads --------------------

// specBuilderTemplate is the DISCOVER-phase prompt, written to
// .piezas/spec-builder.md. It ships with the binary that enforces the formats
// it teaches, so the guide and `spec check` can never drift apart. Two
// mechanisms carry it: mine artifacts and
// PROPOSE a draft (LLMs are excellent at "correct this", poor at "interview
// until done"), then let the checker's named gaps drive the remaining work.
export function specBuilderTemplate() {
  return `${PIEZAS_SPEC_START}
# Piezas spec mode

Your job in this mode is one file: \`SPEC.md\` — the requirements this app is
built, tested and shipped against. You are the product manager for a
non-technical customer. Only they know their business; you own getting it
written down in a form a machine can check.

Write no application code in this mode. Stop when the spec is complete.

Start by running \`npx piezas phase init\` (creates \`SPEC.md\` and the project
state), then \`npx piezas phase status --context\` to see where the project is.

## 1. Mine their artifacts before you ask anything

Their business is already written down somewhere. Reading beats interviewing.

- Ask once, up front: "What do you already have? Spreadsheets, a current site or
  app, forms, exports, screenshots, sketches, an SOP doc, past invoices, an
  email thread — anything. Point me at the folder or paste the paths."
- Read what they give you and mine it into claims. Column headers are entities
  and fields. Status values are workflow states. Form fields are required
  inputs. Repeated manual steps are automations. Notes in the margins are the
  edge cases that matter most.
- Record where every claim came from, inline:
  \`- R-004: An invoice may be split across two projects. (from billing-2025.xlsx, "Split %" column)\`
- Provenance is not decoration: it is what lets a reviewer — or an engineer
  picking this up cold — trust a claim without re-interviewing the customer.

Never ask for something you can read. Never guess at a file you cannot open —
ask them to paste it.

## 2. Propose a complete draft, then interview by delta

An open-ended interview is the failure mode: it exhausts the customer and still
misses things.

- Pick the closest recipe (booking site, CRM/projects/finance, client-services
  portal) and write a complete first-pass understanding from their artifacts:
  entities, roles, the main flows, the obvious edge cases.
- Present it as a draft to correct, not a questionnaire to fill: "Here's what I
  think you need — tell me where I'm wrong."
- Then ask only about the DELTAS: what the recipe assumes that they contradict,
  and what their artifacts show that the recipe has no place for.

**One question at a time.** Never a numbered list. Ask, listen, write it into
\`SPEC.md\`, then ask the next one. Ask about consequences in their language —
"When two people book the same slot, who wins?", not "What is your concurrency
strategy?" Prioritise what changes the build: money, permissions, who sees
what, what happens when something fails, and what they do today when the happy
path breaks.

## 3. Write every agreed answer down immediately, as a pair

The moment the customer confirms something, write both halves. Never batch it.

\`\`\`markdown
## Requirements

- R-007: Staff can cancel a booking up to 24h before it starts. (from the intake call)

## Acceptance Scenarios

### S-011: Staff cancels inside the cancellation window

covers: R-007
Given a booking that starts in 48 hours
When a staff member cancels it
Then the slot returns to availability and the guest is notified
\`\`\`

The formats are exact — \`npx piezas spec check\` parses them:

- \`- R-nnn: <claim>\` lines under \`## Requirements\`.
- \`### S-nnn: <title>\` blocks under \`## Acceptance Scenarios\`, each with a
  \`covers:\` line naming the requirements it proves and its own Given, When and
  Then lines.
- Every R-nnn must be named by some scenario's \`covers:\`.
- No unresolved markers anywhere in the file (the checker rejects TBD, TODO,
  UNRESOLVED and bracketed question marks). A placeholder is an unasked
  question — ask it now instead of parking it.
- \`## Open Conflicts\` must read \`none\`. When the customer says two things that
  cannot both be true, list the conflict there, resolve it with them
  explicitly, then delete it. Never silently pick a side.

Write scenarios about observable behaviour — what the customer would see
happen — never about implementation.

## 4. Let the verdict drive the work

After every meaningful edit, run \`npx piezas spec check\` and work the gaps it
names, one at a time:

- \`SPEC02\` — no requirements yet. Keep interviewing.
- \`SPEC03\` — a scenario is missing a Given/When/Then line. Finish it.
- \`SPEC04: R-007 has no covering scenario\` — ask the customer how they would
  know R-007 works, and write their answer as a scenario.
- \`SPEC05\` — a placeholder is still in the file. Ask the question it stands for.
- \`SPEC06\` — an open conflict. Get the decision.

## 5. Stop at spec completion

When it prints \`spec check: ok\`, summarise the spec back to the customer in
their own words, ask what is obviously missing, and stop. Later each S-nnn gets
a test at \`tests/scenarios/S-nnn.spec.ts\` and the build begins; neither belongs
in this mode. Post-launch changes re-enter this same loop as a small delta:
mine what changed, propose, interview the delta, add R-/S- pairs, re-check.
`;
}

// --- phase: the only state mutators ---------------------------------------

export function approvalFor(state, gate) {
  return state.approvals.find((entry) => entry.gate === gate);
}

// gateGaps answers "what is between this project and the next phase?" — the
// same list drives status, --context, advance and the discover block message.
export function gateGaps(root, state) {
  if (state.phase === 'discover') return checkSpec(root).gaps;
  if (state.phase === 'mock') {
    const approval = approvalFor(state, 'mock')
      ? []
      : [gap('GATE', 'the user has not approved the mock — show it to them, then run `npx piezas phase approve --gate mock`')];
    return [...approval, ...importGaps(root, 'mock')];
  }
  if (state.phase === 'build') return [...checkCoverage(root).gaps, ...importGaps(root, 'build')];
  return [];
}

export const PHASE_ALLOWED = {
  discover: `${SPEC_FILE}, ${STATE_DIR}/**, docs/** — interview and spec work only`,
  mock: 'UI files and fake/seed data — the customer must be able to react to it',
  build: 'everything: real SDK calls, API routes, and one test per scenario',
  ship: 'deploy — the platform accepts the attested test run',
};
export const PHASE_BLOCKED = {
  discover: 'all application code (the PreToolUse hook rejects the write)',
  mock: `${STATE_DIR}/${STATE_FILE} writes, app/api/**, and any file importing @piezas/sdk`,
  build: `${STATE_DIR}/${STATE_FILE} writes`,
  ship: `${STATE_DIR}/${STATE_FILE} writes`,
};
export const PHASE_GATE_TEXT = {
  discover: '`npx piezas spec check` passes, then `npx piezas phase advance`',
  mock: 'the USER approves the mock (`/piezas:approve` -> `npx piezas phase approve --gate mock`), then `npx piezas phase advance`',
  build: 'scenario coverage: every S-nnn in SPEC.md has tests/scenarios/S-nnn.spec.ts|js, then `npx piezas phase advance`',
  ship: 'server-side deploy attestation — the platform is the last gate',
};

export function approvalsLine(state) {
  if (state.approvals.length === 0) return 'approvals: none';
  return `approvals: ${state.approvals.map((entry) => `${entry.gate}@${entry.at}`).join(', ')}`;
}

export function statusLines(state, gaps) {
  const lines = [
    `phase: ${state.phase}`,
    approvalsLine(state),
    `gate: ${GATE_BY_PHASE[state.phase]}`,
    `gaps: ${gaps.length}`,
    ...gapLines(gaps),
  ];
  return lines;
}

// contextLines is what SessionStart injects: everything a fresh session needs
// to resume mid-project — the phase, its rules, and the named gaps. State makes
// sessions disposable; this block is how the state reaches the model.
export function contextLines(state, gaps) {
  return [
    '<piezas-protocol>',
    `phase: ${state.phase}`,
    `allowed: ${PHASE_ALLOWED[state.phase]}`,
    `blocked: ${PHASE_BLOCKED[state.phase]}`,
    `gate: ${PHASE_GATE_TEXT[state.phase]}`,
    approvalsLine(state),
    `gaps: ${gaps.length}`,
    ...gapLines(gaps),
    'rules: phase changes ONLY through `npx piezas phase ...`; never edit .piezas/state.json.',
    '</piezas-protocol>',
  ];
}

export function phaseStatus(startDir = process.cwd(), options = {}) {
  // No project yet is a normal answer (an agent asks before starting one),
  // not an error: exit 0 and say how to begin.
  if (!findProjectRoot(startDir)) {
    const json = { command: 'phase status', projectRoot: null, phase: null, gaps: [] };
    return {
      exitCode: 0,
      ...json,
      json,
      output: ['phase: none — there is no Piezas project in this folder yet', 'start: piezas init --sandbox --app "<App name>" --yes (no account needed)'],
    };
  }
  const root = requireProjectRoot(startDir);
  const state = loadState(root);
  const gaps = gateGaps(root, state);
  const json = {
    command: 'phase status',
    projectRoot: root,
    version: state.version,
    phase: state.phase,
    approvals: state.approvals,
    gate: GATE_BY_PHASE[state.phase],
    gaps,
    createdAt: state.createdAt,
    updatedAt: state.updatedAt,
  };
  // status REPORTS; it never fails. The SessionStart hook depends on it, and
  // `advance` is the command whose exit code is a verdict.
  return {
    exitCode: 0,
    ...json,
    json,
    output: options.context ? contextLines(state, gaps) : statusLines(state, gaps),
  };
}

export function phaseInit(startDir = process.cwd()) {
  const existingRoot = findProjectRoot(startDir);
  const root = existingRoot ?? resolve(startDir);
  const created = [];

  if (!existingRoot) {
    saveState(root, { phase: 'discover', approvals: [], createdAt: new Date().toISOString() });
    created.push(STATE_REL);
  }
  const specPath = join(root, SPEC_FILE);
  if (!existsSync(specPath)) {
    writeFileSync(specPath, specTemplate());
    created.push(SPEC_FILE);
  }
  // The interview guide travels with the state: `phase init` is the protocol's
  // entry point for a project that never ran `piezas init` (or whose session is
  // fresh), and DISCOVER without the guide is a blank page.
  const builderPath = join(root, STATE_DIR, 'spec-builder.md');
  if (!existsSync(builderPath)) {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(builderPath, specBuilderTemplate());
    created.push(`${STATE_DIR}/spec-builder.md`);
  }

  const status = phaseStatus(root);
  return {
    exitCode: 0,
    command: 'phase init',
    projectRoot: root,
    phase: status.phase,
    created,
    json: { ...status.json, command: 'phase init', created },
    output: [...created.map((file) => `created: ${file}`), ...status.output],
  };
}

export function phaseApprove(startDir = process.cwd(), options = {}) {
  const root = requireProjectRoot(startDir);
  const state = loadState(root);
  const gate = typeof options.gate === 'string' ? options.gate.trim() : '';

  if (!APPROVAL_GATES.has(gate)) {
    return {
      exitCode: 1,
      command: 'phase approve',
      json: { command: 'phase approve', ok: false, gate: gate || null, phase: state.phase },
      output: [`refused: unknown gate ${JSON.stringify(gate)} — the only recorded approval is --gate mock`],
    };
  }
  if (state.phase !== gate) {
    return {
      exitCode: 1,
      command: 'phase approve',
      json: { command: 'phase approve', ok: false, gate, phase: state.phase },
      output: [
        `refused: approve --gate ${gate} requires phase=${gate} (current: ${state.phase})`,
        `gate: ${GATE_BY_PHASE[state.phase]}`,
      ],
    };
  }

  const existing = approvalFor(state, gate);
  if (existing) {
    return {
      exitCode: 0,
      command: 'phase approve',
      json: { command: 'phase approve', ok: true, gate, phase: state.phase, approval: existing, recorded: false },
      output: [`approved: ${gate} (already recorded at ${existing.at})`],
    };
  }

  const approval = { gate, by: 'user', at: new Date().toISOString() };
  const saved = saveState(root, { ...state, approvals: [...state.approvals, approval] });
  return {
    exitCode: 0,
    command: 'phase approve',
    json: { command: 'phase approve', ok: true, gate, phase: saved.phase, approval, recorded: true },
    output: [`approved: ${gate}`, `by: ${approval.by}`, `at: ${approval.at}`, 'next: npx piezas phase advance'],
  };
}

export function phaseAdvance(startDir = process.cwd()) {
  const root = requireProjectRoot(startDir);
  const state = loadState(root);
  const next = NEXT_PHASE[state.phase];

  if (!next) {
    return {
      exitCode: 1,
      command: 'phase advance',
      json: { command: 'phase advance', ok: false, phase: state.phase, gaps: [] },
      output: [
        'blocked: ship is the final local phase',
        `gate: ${PHASE_GATE_TEXT.ship}`,
      ],
    };
  }

  // BUILD -> SHIP checks that a test FILE exists per scenario; it does not run
  // the suite. Suite-green is enforced where it cannot be faked — the deploy
  // attestation the platform accepts server-side.
  // The never-rules hold at every step change, whether or not a hook ran. An
  // imported app may describe and preview what it already has (its inherited
  // findings are the build's work order), but leaving the build needs them all
  // fixed: the build-step hard stop has no exceptions.
  const found = next === 'ship' ? hardNoFindings(root) : newHardNoFindings(root);
  const hardNo = found.map((f) => gap(f.code, `${f.file ?? ''}: ${f.message}`));
  const gaps = [...hardNo, ...gateGaps(root, state)];
  if (gaps.length > 0) {
    return {
      exitCode: 1,
      command: 'phase advance',
      json: { command: 'phase advance', ok: false, phase: state.phase, to: next, gaps },
      output: [`blocked: ${state.phase} -> ${next}`, ...gapLines(gaps), `gate: ${GATE_BY_PHASE[state.phase]}`],
    };
  }

  const saved = saveState(root, { ...state, phase: next });
  return {
    exitCode: 0,
    command: 'phase advance',
    json: { command: 'phase advance', ok: true, phase: saved.phase, from: state.phase, to: next, gaps: [] },
    output: [
      `advanced: ${state.phase} -> ${next}`,
      `allowed: ${PHASE_ALLOWED[next]}`,
      `gate: ${PHASE_GATE_TEXT[next]}`,
    ],
  };
}

// --- phase guard: the PreToolUse verdict ----------------------------------

// Write-ish shell patterns. A command that merely READS state.json is fine;
// one that could rewrite it is not, whatever the phase.
export const WRITEISH_SHELL = [
  />/,
  /(^|[\s;|&(])(mv|cp|rm|tee|truncate|install)(\s|$)/,
  /(^|[\s;|&(])sed\b[^\n]*\s-i\b/,
];
export const MENTIONS_STATE_FILE = /(?:\.piezas[/\\]state\.json)|(?:(?:^|[\s'"(=])state\.json)/;
export const STATE_WRITE_BLOCK =
  `Piezas: ${STATE_REL} is protocol state, not a file to edit. Phase and approvals change ONLY through ` +
  '`npx piezas phase init|approve|advance` — rewriting the file by hand (or through the shell) is the one ' +
  'thing that can never be allowed. Run `npx piezas phase status` to see where the project actually is.';

export const MENTIONS_IMPORT_FILE = /(?:\.piezas[/\\]import\.json)|(?:(?:^|[\s'"(=])import\.json)/;
export const IMPORT_WRITE_BLOCK =
  'Piezas: .piezas/import.json records what the imported app came with and what the owner chose. It changes only through ' +
  '`piezas import scan`, and the owner\'s own replies to `piezas import ask`. Do not edit it by hand.';

export function guardAllow() {
  return { exitCode: 0, verdict: 'allow', reason: '' };
}

export function guardBlock(reason) {
  return { exitCode: 2, verdict: 'block', reason };
}

// phaseGuard is called by the plugin's PreToolUse hook for every Write/Edit/Bash
// call. Exit 0 = allow (silent), exit 2 = block with the reason on stderr, which
// Claude Code feeds back to the model — a machine-generated prompt, not a wall.
export function phaseGuard(options = {}) {
  const cwd = resolve(options.cwd || process.cwd());
  // Locate the project from the file being written when there is one: the
  // session may have been opened in a parent folder of the app.
  const target = typeof options.file === 'string' && options.file ? resolve(cwd, options.file) : undefined;
  const root = (target && findProjectRoot(dirname(target))) || findProjectRoot(cwd);
  // Deleting apps and passing secret values hold wherever the plugin runs,
  // project or not: they act on the person's Piezas account, not on files.
  if (options.tool === 'Bash' && typeof options.command === 'string') {
    const outside = accountActionVerdict(stripHeredocBodies(options.command));
    if (outside) return outside;
  }
  // Not a protocol project: the guard has no jurisdiction here.
  if (!root) return guardAllow();

  let state;
  try {
    state = loadState(root);
  } catch (error) {
    // Unreadable state is indistinguishable from tampered state. Blocked
    // project beats shipped lie.
    return guardBlock(`Piezas: ${error.message}`);
  }

  const tool = typeof options.tool === 'string' ? options.tool : '';
  const filePath = target;
  const command = typeof options.command === 'string' ? options.command : '';

  // 1. The state file is off-limits to every tool in every phase. So is the
  //    import record: it holds the owner's choices and what the app came with.
  if (filePath && filePath === join(root, STATE_DIR, STATE_FILE)) {
    return guardBlock(STATE_WRITE_BLOCK);
  }
  if (filePath && filePath === join(root, STATE_DIR, IMPORT_FILE)) {
    return guardBlock(IMPORT_WRITE_BLOCK);
  }
  if (tool === 'Bash' && command && MENTIONS_IMPORT_FILE.test(command)
    && (WRITEISH_SHELL.some((re) => re.test(command)) || SCRIPTED_WRITE.test(command))) {
    return guardBlock(IMPORT_WRITE_BLOCK);
  }
  if (tool === 'Bash' && command && MENTIONS_STATE_FILE.test(command)
    && (WRITEISH_SHELL.some((re) => re.test(command)) || SCRIPTED_WRITE.test(command))) {
    return guardBlock(STATE_WRITE_BLOCK);
  }

  // 2. Shell commands: the always-on Hard No rules (approval is the customer's
  //    alone; no local database). Anything else is allowed through — doctor and
  //    the server attestation cover what shell heuristics cannot.
  if (tool === 'Bash') {
    const hardNo = hardNoShellVerdict(command);
    if (hardNo) return hardNo;
    // A shell redirect or tee that writes a file gets the same file rules as a
    // Write — otherwise `cat > lib/db.ts <<EOF` walks around every write rule.
    for (const target of shellWriteTargets(command)) {
      const verdict = phaseGuard({ cwd, tool: 'Write', file: target, content: command });
      if (verdict.exitCode === 2) return verdict;
    }
    return guardAllow();
  }

  const isFileWrite = tool === 'Write' || tool === 'Edit' || tool === 'MultiEdit';
  if (!filePath || !isFileWrite) return guardAllow();

  const relPath = toPosix(relative(root, filePath));
  // Outside the project (temp files, other repos) — not ours to police.
  if (relPath.startsWith('../')) return guardAllow();

  // 3. The Hard No rules hold in EVERY phase. They are exact conditions on the
  //    text being written, so they are enforced here at write time instead of
  //    waiting for doctor (docs: CLAUDE.md instruction-file review, Rec 4).
  const hardNo = hardNoWriteVerdict(relPath, guardContent(options));
  if (hardNo) return hardNo;

  if (state.phase === 'discover') {
    const allowed =
      relPath === SPEC_FILE ||
      relPath.startsWith(`${STATE_DIR}/`) ||
      relPath.startsWith('docs/');
    if (allowed) return guardAllow();
    const gaps = checkSpec(root).gaps;
    const missing = gaps.length > 0 ? gapLines(gaps).join('; ') : 'none — run `npx piezas phase advance`';
    return guardBlock(
      `Piezas: you are in DISCOVER. App code is locked until the spec is complete — ${relPath} is not writable yet. ` +
        `Write only ${SPEC_FILE}, ${STATE_DIR}/**, docs/**. Missing: ${missing}. ` +
        'Go back to the interview, close those gaps in SPEC.md, then run `npx piezas spec check` and `npx piezas phase advance`.',
    );
  }

  if (state.phase === 'mock') {
    const content = guardContent(options);
    const isApiRoute = /(^|\/)app\/api\//.test(relPath);
    // Declaring the dependency (package.json, lock files) is not calling it:
    // the SDK stays installed through the mock so the build step need not re-add it.
    const isManifest = /(^|\/)(package\.json|package-lock\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?)$/.test(relPath);
    const usesSdk = !isManifest && typeof content === 'string' && content.includes('@piezas/sdk');
    if (isApiRoute || usesSdk) {
      const what = isApiRoute ? `${relPath} is an API route` : `${relPath} imports @piezas/sdk`;
      return guardBlock(
        `Piezas: MOCK phase is UI + fake data only — ${what}. Real endpoints and @piezas/sdk calls wait for BUILD, ` +
          'because the point of the mock is that the customer can react to it before anyone pays for wiring. ' +
          'Use local seed data now. When the user says the mock is right: `npx piezas phase approve --gate mock`, then `npx piezas phase advance`.',
      );
    }
    return guardAllow();
  }

  // build / ship: writes are open; doctor and the deploy attestation judge them.
  return guardAllow();
}

